python3 - <<'PY'
from PIL import Image, ImageFont, ImageDraw
im=Image.open('/workspace/chess_board.png').convert('RGB'); px=im.load()
def color(c):
    r,g,b=c
    if r+g+b<300: return 'b'
    if r+g+b>650: return 'w'
    return '.'
occ=[]
for r in range(8):
    for f in range(8):
        cnt=0
        for y in range(r*80,r*80+80,2):
            for x in range(f*80,f*80+80,2):
                if color(px[x,y])!='.': cnt+=1
        if cnt>40: occ.append((r,f))
for r,f in occ:
    pts=[(x,y) for y in range(r*80,r*80+80) for x in range(f*80,f*80+80) if color(px[x,y])!='.']
    xs=[p[0]-f*80 for p in pts]; ys=[p[1]-r*80 for p in pts]
    cs=set(color(px[p[0],p[1]]) for p in pts)
    print(f"r{r} c{f} {8-r}{chr(97+f)} color={'/'.join(sorted(cs))} bbox x{min(xs)}-{max(xs)} y{min(ys)}-{max(ys)} w{max(xs)-min(xs)+1} h{max(ys)-min(ys)+1} n{len(pts)}")
print('--- glyph bbox at sizes ---')
glyphs='♔♕♖♗♘♙♚♛♜♝♞♟'
for path in ['/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/fonts/noto.ttf']:
    print(path)
    for size in [44,48,52,56,60,64,68,72]:
        try:
            font=ImageFont.truetype(path,size)
        except Exception as e:
            print(size,e); continue
        out=[]
        for g in glyphs:
            img=Image.new('L',(120,120),0); d=ImageDraw.Draw(img); d.text((10,10),g,fill=255,font=font)
            bb=img.getbbox()
            if bb: out.append(f"{g}:{bb[2]-bb[0]}x{bb[3]-bb[1]}")
        print(size,' '.join(out))
